CREATE TYPE "Moment" AS ENUM ('FASTING','AFTER_LUNCH','BEFORE_DINNER');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'patient',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Measurement" ("id" TEXT NOT NULL,"patientId" TEXT NOT NULL,"moment" "Moment" NOT NULL,"measuredAt" TIMESTAMP(3) NOT NULL,"value" DECIMAL(5,2) NOT NULL,"requestKey" TEXT,"comment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Measurement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GlucoseTarget" ("id" TEXT NOT NULL,"moment" "Moment" NOT NULL,"low" DECIMAL(5,2),"high" DECIMAL(5,2),"belowIsLow" BOOLEAN NOT NULL DEFAULT true,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GlucoseTarget_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"entityId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Measurement_requestKey_key" ON "Measurement"("requestKey"); CREATE INDEX "Measurement_patientId_measuredAt_idx" ON "Measurement"("patientId","measuredAt"); CREATE UNIQUE INDEX "GlucoseTarget_moment_key" ON "GlucoseTarget"("moment"); CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
ALTER TABLE "Measurement" ADD CONSTRAINT "Measurement_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
INSERT INTO "GlucoseTarget" ("id","moment","low","high","updatedAt") VALUES ('target-fasting','FASTING',4.0,7.0,CURRENT_TIMESTAMP),('target-lunch','AFTER_LUNCH',NULL,8.5,CURRENT_TIMESTAMP),('target-dinner','BEFORE_DINNER',4.0,7.0,CURRENT_TIMESTAMP);
